resources.description:
Sample IAM policies for least privilege access to Amazon Aurora MySQL


*Read Only Policy:*

[source,json,subs="verbatim,attributes"]
----
{
  "Version": "2012-10-17",{tcx5-2025-waiver}
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "rds:Describe*",
        "rds:List*",
        "rds:Get*"
      ],
      "Resource": "*"
    }
  ]
}
----


*Operator Policy:*

[source,json,subs="verbatim,attributes"]
----
{
  "Version": "2012-10-17",{tcx5-2025-waiver}
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "rds:Describe*",
        "rds:List*",
        "rds:Get*",
        "rds:Update*",
        "rds:Put*",
        "rds:Create*"
      ],
      "Resource": "*",
      "Condition": {
        "Bool": {
          "aws:MultiFactorAuthPresent": "true"
        }
      }
    }
  ]
}
----


*Administrator Policy:*

[source,json,subs="verbatim,attributes"]
----
{
  "Version": "2012-10-17",{tcx5-2025-waiver}
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "rds:*",
      "Resource": "*",
      "Condition": {
        "Bool": {
          "aws:MultiFactorAuthPresent": "true"
        },
        "NumericLessThan": {
          "aws:MultiFactorAuthAge": "3600"
        }
      }
    }
  ]
}
----
